package com.prudence.oversight;
import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/oversight") public class HumanOversightController {private final HumanAssignmentRepository repo; private final HumanOverrideRepository overrides; public HumanOversightController(HumanAssignmentRepository r,HumanOverrideRepository o){repo=r;overrides=o;} @GetMapping("/systems/{id}/assignments") public List<HumanAssignmentJpaEntity> list(@PathVariable String id){return repo.findByAiSystemId(id);}@PostMapping("/systems/{id}/assignments") public HumanAssignmentJpaEntity assign(@PathVariable String id,@RequestBody Body b){if(b.person==null||b.trainingEvidence==null||b.trainingExpiresAt==null)throw new IllegalArgumentException("person, training evidence and expiry required");return repo.save(new HumanAssignmentJpaEntity(UUID.randomUUID().toString(),id,b.role,b.person,b.overrideAuthority,b.stopAuthority,b.trainingEvidence,b.trainingExpiresAt));}@PostMapping("/systems/{id}/overrides") public HumanOverrideJpaEntity override(@PathVariable String id,@RequestBody OverrideBody b){return overrides.save(new HumanOverrideJpaEntity(UUID.randomUUID().toString(),id,b.aosReference,b.supervisor,b.reason,b.outcome,java.time.Instant.now().toString()));}@PostMapping("/overrides/{id}/review") public HumanOverrideJpaEntity review(@PathVariable String id,@RequestBody ReviewBody b){var o=overrides.findById(id).orElseThrow();o.review(b.reviewer,b.note,java.time.Instant.now().toString());return overrides.save(o);} public record Body(OversightRole role,String person,boolean overrideAuthority,boolean stopAuthority,String trainingEvidence,String trainingExpiresAt){} public record OverrideBody(String aosReference,String supervisor,String reason,String outcome){} public record ReviewBody(String reviewer,String note){} }
